team_join_requests_decision_check.value:
(
      "team_join_requests"."status" = 'pending' and "team_join_requests"."decided_at" is null and "team_join_requests"."decided_by_user_id" is null
    ) or (
      "team_join_requests"."status" in ('approved', 'rejected') and "team_join_requests"."decided_at" is not null and "team_join_requests"."decided_by_user_id" is not null
    ) or (
      "team_join_requests"."status" = 'cancelled' and "team_join_requests"."decided_at" is not null
    )
